let record = $input.item.json?.record
let propertyID_prefix = $input.item.json?.propertyID_prefix || undefined

if(record === undefined || record === null){
    return {}
  }

for(let x=0; x< 5; x++){

  let propertyID = $input.item.json?.['propertyID' + String(x)]
  let value = $input.item.json?.['value' + String(x)]

  if(propertyID === undefined || propertyID === null){
    continue
  }

  if(propertyID_prefix){
    propertyID = propertyID_prefix + '.' + propertyID
  }

  record = setValue(record, propertyID, value)

}

return record
